#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/srotmg.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/assert/is_nanf.h"

/**
* Constructs a modified Givens plane rotation using alternative indexing semantics.
*
* @param d1        scaling factor for the first vector component
* @param d2        scaling factor for the second vector component
* @param x1        first component of the first vector
* @param y1        first component of the second vector
* @param Out     output array
* @param strideOut    index increment
* @param offsetOut    starting index
*/
void API_SUFFIX( c_srotmg_assign )( float d1, float d2, float x1, const float y1, float *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	const float GAM = 4096.0f;
	const float GAM_SQ = 16777216.0f;
	const float RGAM_SQ = 5.9604645e-8f;

	float flag;
	float temp;
	float ad1;
	float ad2;
	float h11 = 0.0f;
	float h12 = 0.0f;
	float h21 = 0.0f;
	float h22 = 0.0f;
	float p1;
	float p2;
	float q1;
	float q2;
	float u;

	// Check for NaN inputs
	if ( stdlib_base_is_nanf( d1 ) || stdlib_base_is_nanf( d2 ) || stdlib_base_is_nanf( x1 ) || stdlib_base_is_nanf( y1 ) ) {
		Out[ offsetOut ] = 0.0f / 0.0f;  // NaN
		Out[ offsetOut + strideOut ] = 0.0f / 0.0f;
		Out[ offsetOut + ( 2 * strideOut ) ] = 0.0f / 0.0f;
		Out[ offsetOut + ( 3 * strideOut ) ] = 0.0f / 0.0f;
		Out[ offsetOut + ( 4 * strideOut ) ] = 0.0f / 0.0f;
		return;
	}

	if ( d1 < 0.0f ) {
		flag = -1.0f;
		h11 = 0.0f;
		h12 = 0.0f;
		h21 = 0.0f;
		h22 = 0.0f;
		d1 = 0.0f;
		d2 = 0.0f;
		x1 = 0.0f;
	} else {
		p2 = d2 * y1;
		if ( p2 == 0.0f ) {
			flag = -2.0f;
			Out[ offsetOut ] = flag;
			return;
		}
		p1 = d1 * x1;
		q2 = p2 * y1;
		q1 = p1 * x1;
		ad1 = stdlib_base_absf( q1 );
		ad2 = stdlib_base_absf( q2 );

		if ( ad1 > ad2 ) {
			h21 = -y1 / x1;
			h12 = p2 / p1;
			u = 1.0f - ( h12 * h21 );
			if ( u > 0.0f ) {
				flag = 0.0f;
				d1 = d1 / u;
				d2 = d2 / u;
				x1 = x1 * u;
			}
		} else if ( q2 < 0.0f ) {
			flag = -1.0f;
			h11 = 0.0f;
			h12 = 0.0f;
			h21 = 0.0f;
			h22 = 0.0f;
			d1 = 0.0f;
			d2 = 0.0f;
			x1 = 0.0f;
		} else {
			flag = 1.0f;
			h11 = p1 / p2;
			h22 = x1 / y1;
			u = 1.0f + ( h11 * h22 );
			temp = d2 / u;
			d2 = d1 / u;
			d1 = temp;
			x1 = y1 * u;
		}

		if ( d1 != 0.0f ) {
			while ( ( d1 < RGAM_SQ ) || ( d1 > GAM_SQ ) ) {
				if ( flag == 0.0f ) {
					h11 = 1.0f;
					h22 = 1.0f;
					flag = -1.0f;
				} else {
					h21 = -1.0f;
					h12 = 1.0f;
					flag = -1.0f;
				}
				if ( d1 < RGAM_SQ ) {
					d1 = d1 * GAM * GAM;
					x1 = x1 / GAM;
					h11 = h11 / GAM;
					h12 = h12 / GAM;
				} else {
					d1 = d1 / ( GAM * GAM );
					x1 = x1 * GAM;
					h11 = h11 * GAM;
					h12 = h12 * GAM;
				}
			}
		}

		if ( d2 != 0.0f ) {
			while ( ( stdlib_base_absf( d2 ) < RGAM_SQ ) || ( stdlib_base_absf( d2 ) > GAM_SQ ) ) {
				if ( flag == 0.0f ) {
					h11 = 1.0f;
					h22 = 1.0f;
					flag = -1.0f;
				} else {
					h21 = -1.0f;
					h12 = 1.0f;
					flag = -1.0f;
				}
				if ( stdlib_base_absf( d2 ) < RGAM_SQ ) {
					d2 = d2 * GAM * GAM;
					h21 = h21 / GAM;
					h22 = h22 / GAM;
				} else {
					d2 = d2 / ( GAM * GAM );
					h21 = h21 * GAM;
					h22 = h22 * GAM;
				}
			}
		}
	}

	Out[ offsetOut ] = flag;

	if ( flag < 0.0f ) {
		Out[ offsetOut + strideOut ] = h11;
		Out[ offsetOut + ( 2 * strideOut ) ] = h21;
		Out[ offsetOut + ( 3 * strideOut ) ] = h12;
		Out[ offsetOut + ( 4 * strideOut ) ] = h22;
	} else if ( flag == 0.0f ) {
		Out[ offsetOut + ( 2 * strideOut ) ] = h21;
		Out[ offsetOut + ( 3 * strideOut ) ] = h12;
	} else {
		Out[ offsetOut + strideOut ] = h11;
		Out[ offsetOut + ( 4 * strideOut ) ] = h22;
	}

	return;
}
